{"description":"验证图片解码尺寸和请求映射","command":"python3 - <<'PY'
import json, subprocess, pathlib, hashlib
runs=json.load(open('media.json'))['runs']; subs=json.load(open('submission.json'))['items']; manifest=json.load(open('manifest.json'))['items']; results=[]
for n,(r,s,m) in enumerate(zip(runs,subs,manifest),1):
 try:
  assert r['status']=='succeeded' and r['request_id']==s['request_id']==m['request_id'] and r['run_id']==s['run_id'] and len(r['images'])==1
  im=r['images'][0]; p=pathlib.Path(im['file_path']); data=p.read_bytes(); assert data[:8]==b'\x89PNG\r\n\x1a\n'
  import struct,zlib
  pos=8; chunks=[]; wh=None
  while pos<len(data):
   length=struct.unpack('>I',data[pos:pos+4])[0]; typ=data[pos+4:pos+8]; payload=data[pos+8:pos+8+length]; crc=struct.unpack('>I',data[pos+8+length:pos+12+length])[0]; assert zlib.crc32(typ+payload)&0xffffffff==crc
   if typ==b'IHDR': wh=struct.unpack('>II',payload[:8])
   if typ==b'IDAT': chunks.append(payload)
   pos+=12+length
   if typ==b'IEND': break
  assert wh==(512,512) and pos==len(data); assert zlib.decompress(b''.join(chunks))
  assert r['parameters']['positive_prompt']==pathlib.Path(m['parameter_files']['positive_prompt']).read_bytes().decode('utf-8') and r['parameters']['seed']==424241+n
  results.append({'number':n,'run_id':r['run_id'],'request_id':r['request_id'],'media_id':im['media_id'],'file_path':str(p),'size':list(wh),'sha256':hashlib.sha256(data).hexdigest(),'readable':True})
  print(n,'OK',wh,len(data))
 except Exception as e:
  print(n,'FAILED',repr(e)); raise
pathlib.Path('verification.json').write_text(json.dumps(results,ensure_ascii=False,indent=2)+'\n')
PY"}

